<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import CompanyAccountConnection from './CompanyAccountConnection.svelte';
 import {CompanyProvidersClient,authUrl,type Provider,type Connection,type Option,type Selection,type LoginSession} from './providers-client';
 export let companyId:string;
 export let accessSignal:AbortSignal;
 let watchedSignal:AbortSignal|undefined;
 export let bots:{id:string;name:string}[]=[];
 const dispatch=createEventDispatcher<{changed:{companyId:string;kind:string;botId?:string}}>();
 let client:CompanyProvidersClient,loaded='',mounted=false,generation=0,busy=false,loading=true,error='',notice='',canManage=false;
 let endpointKinds:string[]=[],endpointKind='ollama',endpointUrl='',endpointKey='',endpointModels='',endpointTarget='';
 let authCatalogReady=false,imageConfigured=false,subscriptionConsent=false,keyPurpose:'images'|'inference'='images';
 let providers:Provider[]=[],connections:Connection[]=[],query='',providerId='',key='',rotating:Connection|null=null,session:LoginSession|null=null,answer='',timer:ReturnType<typeof setTimeout>|undefined;
 let companyDefault:Selection|null=null,defaultOptions:Option[]=[],defaultChoice='',botId='',botSelection:Selection|null=null,botOptions:Option[]=[],botChoice='';
 const choiceKey=(c:Option|Selection,m:string)=>JSON.stringify([c.connectionId,m]);
 const isChoice=(items:Option[],value:string)=>items.some(o=>o.models.some(m=>choiceKey(o,m)===value));
 const searchText=(p:Provider)=>p.name+' '+p.id+(p.id==='anthropic'?' Claude':p.id==='openai'?' ChatGPT Codex':p.id==='xai'?' Grok SuperGrok X Premium':'');
 $: filtered=providers.filter(p=>searchText(p).toLowerCase().includes(query.toLowerCase()));
 $: if(filtered.length&&!filtered.some(p=>p.id===providerId)){providerId=filtered[0].id;key='';rotating=null;subscriptionConsent=false;keyPurpose=providerId==='openai'?'images':'inference';}
 $: selectedProvider=providers.find(p=>p.id===providerId);
 $: if(mounted&&watchedSignal!==accessSignal){watchedSignal?.removeEventListener('abort',accessRevoked);watchedSignal=accessSignal;if(accessSignal.aborted)accessRevoked();else accessSignal.addEventListener('abort',accessRevoked,{once:true});}
 $: if(mounted&&!accessSignal.aborted&&loaded!==companyId){loaded=companyId;void reset();}
 function clearTimer(){if(timer)clearTimeout(timer);timer=undefined;}
 function changed(kind:string,id?:string){dispatch('changed',{companyId,kind,...(id?{botId:id}:{})});}
 async function reset(){const n=++generation;clearTimer();client?.close();client=new CompanyProvidersClient(companyId,()=>localStorage.token||'');key='';endpointKey='';endpointKinds=[];endpointUrl='';endpointModels='';endpointTarget='';rotating=null;answer='';session=null;companyDefault=null;botSelection=null;defaultOptions=[];botOptions=[];connections=[];providers=[];authCatalogReady=false;imageConfigured=false;subscriptionConsent=false;botId='';busy=false;error='';notice='';await load(n);}
 async function load(n=generation){loading=true;const current=client;try{const [connectionResult,defaultResult,authResult]=await Promise.allSettled([current.connections(),current.default(),current.authCatalog()]);if(n!==generation||current!==client)return;if(connectionResult.status==='rejected')throw connectionResult.reason;const d=connectionResult.value;connections=d.connections;providers=d.providers;canManage=d.canManage;authCatalogReady=authResult.status==='fulfilled';endpointKinds=[];if(authResult.status==='fulfilled'){providers=authResult.value.providers;imageConfigured=authResult.value.image?.configured===true;endpointKinds=(authResult.value.endpointKinds||[]).filter(kind=>['ollama','openai-compatible'].includes(kind));if(endpointKinds.length&&!endpointKinds.includes(endpointKind))endpointKind=endpointKinds[0];canManage=canManage&&authResult.value.canManage;}companyDefault=null;defaultOptions=[];defaultChoice='';if(defaultResult.status==='fulfilled'){const def=defaultResult.value;companyDefault=def.selection;defaultOptions=def.options;defaultChoice=def.selection.connectionId&&def.selection.model?choiceKey(def.selection,def.selection.model):'';}if(!providers.some(p=>p.id===providerId))providerId=providers.find(p=>p.id==='openai')?.id||providers[0]?.id||'';}catch(e){if(n===generation)error=(e as Error).message||'Company providers could not be loaded.';}finally{if(n===generation)loading=false;}}
 async function loadBot(){const current=client,n=generation,id=botId;botSelection=null;botOptions=[];botChoice='';if(!id)return;try{const d=await current.bot(id);if(current!==client||n!==generation||id!==botId)return;botSelection=d.selection;botOptions=d.options;botChoice=d.selection.model?choiceKey(d.selection,d.selection.model):'';}catch(e){if(n===generation&&id===botId)error=(e as Error).message;}}
 async function action(task:()=>Promise<unknown>,message:string,kind:string){if(busy)return;busy=true;error='';notice='';const n=generation;try{await task();if(n!==generation)return;notice=message;await load(n);await loadBot();changed(kind,kind==='bot'?botId:undefined);}catch(e){if(n===generation)error=(e as Error).message||'The change could not be confirmed. Reload before trying again.';}finally{if(n===generation)busy=false;}}
 async function saveKey(){if(!key.trim()||!providerId)return;const secret=key,target=rotating;key='';rotating=null;await action(()=>target?client.rotate(target,secret):authCatalogReady?client.privateKey(providerId,secret,providerId==='openai'?keyPurpose:'inference'):client.connect(providerId,secret),target?'Company credential replaced. Existing bot choices are retained.':authCatalogReady&&providerId==='openai'&&keyPurpose==='images'?'Image API key connected. Existing Codex inference remains unchanged.':'Company connection added. Existing bot model choices are unchanged.','connection');}
 async function saveDefault(){if(!companyDefault||!isChoice(defaultOptions,defaultChoice))return;const [connectionId,model]=JSON.parse(defaultChoice);await action(()=>client.saveDefault(companyDefault!,connectionId,model),'Company default saved. Existing bot choices are unchanged.','default');}
 async function saveBot(){if(!botSelection||!isChoice(botOptions,botChoice))return;const [connectionId,model]=JSON.parse(botChoice);await action(()=>client.saveBot(botId,botSelection!,connectionId,model),'Bot provider choice saved.','bot');}
 async function acceptSession(next:LoginSession,n:number){if(n!==generation)return;session=next;if(next.status==='CONNECTED'){notice='Company sign-in completed. Choose where to use this connection.';answer='';await load(n);await loadBot();if(n===generation)changed('connection');}else if(next.status==='FAILED'||next.status==='EXPIRED')error=next.error||'Sign-in expired. Start again.';poll();}
 function poll(){clearTimer();if(!session||!['CONNECTING','INPUT_REQUIRED'].includes(session.status))return;const n=generation,current=client,id=session.id;timer=setTimeout(async()=>{try{const next=await current.status(id);if(n!==generation||current!==client||session?.id!==id)return;await acceptSession(next,n);}catch(e){if(n===generation){clearTimer();error=(e as Error).message;session=null;answer='';}}},1200);}

 async function startLogin(type:'api_key'|'oauth'){if(busy||!providerId||authCatalogReady&&!subscriptionConsent)return;busy=true;error='';notice='';const n=generation;try{if(session&&['CONNECTING','INPUT_REQUIRED'].includes(session.status))await client.cancel(session.id);const next=await client.start(providerId,type);if(n!==generation)return;answer='';await acceptSession(next,n);}catch(e){if(n===generation)error=(e as Error).message;}finally{if(n===generation)busy=false;}}
 async function submitAnswer(){if(!session?.prompt||!answer.trim()||busy)return;busy=true;error='';const n=generation,id=session.id,promptId=session.prompt.id,value=answer;answer='';try{const next=await client.answer(id,promptId,value);if(n!==generation)return;await acceptSession(next,n);}catch(e){if(n===generation)error=(e as Error).message;}finally{if(n===generation)busy=false;}}
 async function cancelLogin(){if(!session||busy)return;clearTimer();const id=session.id;await action(async()=>{session=await client.cancel(id);answer='';},'Sign-in cancelled.','login');}
 async function saveEndpoint(){if(!endpointKinds.includes(endpointKind)||!endpointUrl.trim()||busy)return;const configuration={kind:endpointKind,baseUrl:endpointUrl.trim(),...(endpointKey?{apiKey:endpointKey}:{}),...(endpointModels.trim()?{modelIds:[...new Set(endpointModels.split(/[,\n]/).map(v=>v.trim()).filter(Boolean))]}:{}),...(endpointTarget.trim()?{targetId:endpointTarget.trim()}:{} )};endpointKey='';await action(()=>client.endpoint(configuration),'Endpoint connection verified. Choose its model for a bot below; existing bot choices are unchanged.','connection');}
 function accessRevoked(){generation++;clearTimer();client?.close();session=null;rotating=null;key='';endpointKey='';endpointKinds=[];endpointUrl='';endpointModels='';endpointTarget='';answer='';canManage=false;providers=[];connections=[];companyDefault=null;botSelection=null;loading=false;busy=false;error='Company access changed. Reopen this company.';}
 function sessionChanged(e:StorageEvent){if(e.key==='token'||e.key===null)accessRevoked();}

 onMount(()=>{mounted=true;window.addEventListener('storage',sessionChanged);return()=>window.removeEventListener('storage',sessionChanged);});
 onDestroy(()=>{watchedSignal?.removeEventListener('abort',accessRevoked);generation++;clearTimer();key='';endpointKey='';answer='';const old=client,id=session?.id;if(old&&id&&['CONNECTING','INPUT_REQUIRED'].includes(session!.status))void old.cancel(id).catch(()=>{}).finally(()=>old.close());else old?.close();});
</script>
<section class="providers" aria-label="Company providers">
 <header><div><h2>Providers</h2><p>Connect models for this company, set a company default, and choose a model for each bot.</p></div><button class="button secondary" disabled={busy||loading} on:click={()=>{error='';void load();void loadBot();}}>Reload</button></header>
 {#if error}<p class="alert" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
 {#if loading&&!providers.length}<p role="status">Loading installed providers…</p>{:else if providers.length}
 {#if canManage&&!authCatalogReady}<CompanyAccountConnection {companyId} {accessSignal} on:connected={()=>{void load();void loadBot();changed('connection');}}/>{/if}<div class="panel"><div class="section-title"><h3>Company connections</h3><span class="badge">{providers.length} installed providers</span></div>
 <p>Connections are shared within this company. Account-default references keep their existing owner and bot scope.</p>
 {#if canManage}
 <label>Find a provider<input type="search" bind:value={query} placeholder="OpenAI, Claude, xAI…" /></label>
 <label>Provider<select aria-label="Provider" bind:value={providerId} disabled={busy} on:change={()=>{key='';rotating=null;subscriptionConsent=false;keyPurpose=providerId==='openai'?'images':'inference';}}>{#each filtered as p}<option value={p.id}>{p.name}{p.modelCount?' · '+p.modelCount+' models':''}</option>{/each}</select></label>
 {#if selectedProvider&&!authCatalogReady}<div class="provider-detail"><h4>{selectedProvider.name}</h4><div class="actions">{#each selectedProvider.authMethods.filter(m=>m.type==='oauth'&&m.interactive) as method}<button class="button" disabled={busy} on:click={()=>startLogin('oauth')}>{method.label}{method.subscription?' · subscription':''}</button>{/each}</div>
 {#if selectedProvider.authMethods.some(m=>m.type==='api_key')}
 <form on:submit|preventDefault={saveKey}>{#if rotating}<p>Replacing the API key for connection {rotating.connectionId.slice(0,8)}.</p>{/if}<label>API key<input type="password" bind:value={key} autocomplete="new-password" spellcheck={false} disabled={busy} /></label><div class="actions"><button class="button" disabled={busy||!key.trim()}>{rotating?'Replace API key':'Connect API key'}</button>{#if rotating}<button type="button" class="button secondary" on:click={()=>{rotating=null;key='';}}>Cancel replacement</button>{/if}{#if selectedProvider.authMethods.some(m=>m.type==='api_key'&&m.interactive)}<button type="button" class="button secondary" disabled={busy} on:click={()=>startLogin('api_key')}>Guided setup</button>{/if}</div></form>
 {/if}
 <p>Sign in on the provider’s website. Return the one-time code or final redirect URL here if requested. Never enter your account password. Cloud profile and file-based credentials are not read from the server.</p></div>{/if}
 {#if selectedProvider&&authCatalogReady}<div class="provider-detail"><h4>{selectedProvider.name}</h4>{#if !selectedProvider.authMethods.length}<p>The installed SDK does not expose interactive authentication for this provider.</p>{/if}<p>Existing Codex inference and bot model choices remain unchanged when you add a connection.</p>
 {#if selectedProvider.authMethods.some(m=>m.type==='oauth'&&m.interactive)}<label class="consent-label"><input type="checkbox" bind:checked={subscriptionConsent} disabled={busy}/><span>I authorize this account connection for permitted company bots.</span></label><div class="actions">{#each selectedProvider.authMethods.filter(m=>m.type==='oauth'&&m.interactive) as method}<button class="button" disabled={busy||!subscriptionConsent} on:click={()=>startLogin('oauth')}>Sign in · {method.label}</button>{/each}{#if selectedProvider.subscriptionAccountAvailable}<button class="button secondary" disabled={busy||!subscriptionConsent} on:click={()=>action(()=>client.subscription(providerId),'Connected account linked to company. Existing bot models are unchanged.','connection')}>Use my connected account</button>{/if}</div><p>Complete the provider’s secure sign-in below. This does not change your bots’ selected models.</p>{/if}
 {#if selectedProvider.authMethods.some(m=>m.type==='api_key')}<form on:submit|preventDefault={saveKey}><label>Private {selectedProvider.name} API key<input type="password" bind:value={key} autocomplete="new-password" spellcheck={false} disabled={busy}/></label>{#if providerId==='openai'}<label>Use this API key for<select bind:value={keyPurpose} disabled={busy}><option value="images">Image generation only</option><option value="inference">Company model connection</option></select></label><p>{imageConfigured?'Company image generation has a configured API key.':'Image generation requires a separate OpenAI API key.'} Subscription sign-in continues to handle your existing Codex conversations.</p>{/if}<button class="button" disabled={busy||!key.trim()}>Connect API key{providerId==='openai'&&keyPurpose==='images'?' for images':''}</button><p>The key is sent directly to private company settings and cleared from this form. Never paste it into chat.</p></form>{/if}
 </div>{/if}
 {/if}
 {#if session}<div class="login" aria-live="polite"><strong>{providers.find(p=>p.id===session?.provider)?.name||session.provider} · {session.status.toLowerCase().replaceAll('_',' ')}</strong>
 {#each session.events as event}{#if event.type==='auth_url'&&authUrl(event.url)}<p><a href={authUrl(event.url)||undefined} target="_blank" rel="noopener noreferrer">Open secure provider sign-in ↗</a></p>{/if}{#if event.instructions||event.message}<p>{event.instructions||event.message}</p>{/if}{#if event.type==='device_code'}{#if authUrl(event.verificationUri||event.verificationUrl||event.url)}<a href={authUrl(event.verificationUri||event.verificationUrl||event.url)||undefined} target="_blank" rel="noopener noreferrer">Open verification page ↗</a>{/if}<code>{event.userCode||event.code||''}</code>{/if}{/each}
 {#if session.prompt}<form on:submit|preventDefault={submitAnswer}><label>{session.prompt.message}{#if session.prompt.type==='select'}<select aria-label={session.prompt.message} bind:value={answer} disabled={busy}><option value="">Choose an option</option>{#each session.prompt.options||[] as option}<option value={option.id}>{option.label||option.id}</option>{/each}</select>{:else if session.prompt.type==='secret'}<input type="password" bind:value={answer} placeholder={session.prompt.placeholder||''} autocomplete="off" spellcheck={false} disabled={busy} />{:else}<input type="text" bind:value={answer} placeholder={session.prompt.placeholder||''} autocomplete="off" spellcheck={false} disabled={busy} />{/if}</label><button class="button" disabled={busy||!answer.trim()}>Continue sign-in</button></form>{/if}
 {#if ['CONNECTING','INPUT_REQUIRED'].includes(session.status)}<button class="button secondary" disabled={busy} on:click={cancelLogin}>Cancel sign-in</button>{/if}</div>{/if}
 <div class="connections">{#each connections.filter(c=>c.status==='active') as connection}<div class="connection"><div><strong>{providers.find(p=>p.id===connection.provider)?.name||connection.provider}</strong><p>{connection.mode==='account_default'?'Owner account default · bot-scoped reference':'Company connection'} · {connection.connectionId.slice(0,8)} · revision {connection.revision}</p></div>{#if canManage}<div class="actions">{#if !authCatalogReady&&connection.mode!=='account_default'&&providers.find(p=>p.id===connection.provider)?.authMethods.some(m=>m.type==='api_key')}<button class="button secondary" disabled={busy} on:click={()=>{rotating=connection;providerId=connection.provider;query='';key='';}}>Replace API key</button>{/if}<button class="button secondary" disabled={busy} on:click={()=>action(()=>client.refresh(connection),'Model list refreshed.','models')}>Refresh models</button><button class="button danger" disabled={busy} on:click={()=>action(()=>client.revoke(connection),'Connection revoked. Affected bot choices are blocked.','connection')}>Revoke</button></div>{/if}</div>{:else}<p>No active company connections yet.</p>{/each}</div></div>
 {#if canManage&&endpointKinds.length}<div class="panel"><h3>Custom model endpoint</h3><p>Connect Ollama or an OpenAI-compatible service. Existing Codex inference remains unchanged until you explicitly choose a different model for a bot.</p><form on:submit|preventDefault={saveEndpoint}><label>Endpoint type<select bind:value={endpointKind} disabled={busy}>{#each endpointKinds as kind}<option value={kind}>{kind==='ollama'?'Ollama':'OpenAI-compatible'}</option>{/each}</select></label><label>Base URL<input type="url" bind:value={endpointUrl} placeholder={endpointKind==='ollama'?'https://models.example.com':'https://models.example.com/v1'} required disabled={busy}/></label><label>Private endpoint API key <span>(optional)</span><input type="password" bind:value={endpointKey} autocomplete="new-password" spellcheck={false} disabled={busy}/></label><label>Model IDs <span>(optional, comma-separated)</span><input bind:value={endpointModels} placeholder="model-name" disabled={busy}/></label><label>Registered company computer target <span>(optional)</span><input bind:value={endpointTarget} disabled={busy}/></label><p>Public endpoints require HTTPS. Private endpoints require an already registered company-computer target; entering an ID does not register a computer.</p><button class="button" disabled={busy||!endpointUrl.trim()}>Verify and connect endpoint</button></form></div>{/if}
 <div class="panel"><h3>Company default</h3><p>Bots without a saved choice inherit this default. Saving it leaves existing bot choices unchanged.</p>
 {#if !companyDefault}<p>Company defaults are unavailable on this server. You can still save an independent model for each bot below.</p>{/if}{#if companyDefault}<p>Current: {companyDefault.status==='unconfigured'?'Not set':companyDefault.provider+' · '+companyDefault.model+' · '+companyDefault.status.replaceAll('_',' ')}</p><form on:submit|preventDefault={saveDefault}><label>Default provider and model<select aria-label="Default provider and model" bind:value={defaultChoice} disabled={busy||!canManage}><option value="">Choose a connected model</option>{#each defaultOptions as option}{#each option.models as model}<option value={choiceKey(option,model)}>{option.provider} · {option.connectionId?.slice(0,8)} · {model}</option>{/each}{/each}</select></label>{#if canManage}<button class="button" disabled={busy||!isChoice(defaultOptions,defaultChoice)}>Save company default</button>{/if}</form>{/if}</div>
 <div class="panel"><h3>Bot choices</h3><label>Company bot<select aria-label="Company bot" bind:value={botId} disabled={busy} on:change={loadBot}><option value="">Choose a bot</option>{#each bots as bot}<option value={bot.id}>{bot.name}</option>{/each}</select></label>
 {#if botSelection}<p>Saved: {botSelection.provider||'None'}{botSelection.model?' · '+botSelection.model:''} · {botSelection.status.replaceAll('_',' ')}{botSelection.mode==='company_default'?' · inherits company default':''}</p>{#if botSelection.mode==='account_default'}<p>This bot currently follows its owner’s account default. Choose a company connection below to save a different provider and model for this bot.</p>{/if}
 <form on:submit|preventDefault={saveBot}><label>Provider and model<select aria-label="Provider and model" bind:value={botChoice} disabled={busy||!canManage}><option value="">Choose a connected model</option>{#each botOptions as option}{#each option.models as model}<option value={choiceKey(option,model)}>{option.mode==='account_default'?'Owner account default':option.provider==='hosted'?'StarliDigital hosted':option.provider+' · '+option.connectionId?.slice(0,8)} · {model}</option>{/each}{/each}</select></label>{#if canManage}<button class="button" disabled={busy||!isChoice(botOptions,botChoice)}>Save bot choice</button>{/if}</form>{/if}</div>
 {/if}
</section>
<style>
.providers{width:100%;max-width:1040px;min-width:0;margin:0 auto;color:#17233b;color-scheme:light;font-size:14px;line-height:1.5}.providers :global(*){box-sizing:border-box}header,.section-title,.connection{display:flex;align-items:center;justify-content:space-between;gap:16px;min-width:0}header{margin-bottom:24px;align-items:flex-start}header>div{min-width:0;flex:1}header>.button{flex:none}h2{font-size:26px;font-weight:650;letter-spacing:-.6px;line-height:1.3;margin:0 0 10px}h3{font-size:17px;font-weight:650;margin:0}h4{font-size:15px;font-weight:600;margin:0}p{font-size:13px;line-height:1.7;color:#526780;margin:8px 0;overflow-wrap:anywhere}label{display:flex;flex-direction:column;gap:7px;font-size:13px;color:#263b58;font-weight:500;margin:16px 0}input,select{display:block;width:100%;max-width:100%;min-width:0;min-height:43px;background:#fff;border:1px solid #cfd9e8;color:#17233b;border-radius:8px;padding:10px 12px;font:inherit;font-size:13px}input::placeholder{color:#64748b}select{color-scheme:light}input:disabled,select:disabled{background:#f1f5f9;color:#526780}input:focus-visible,select:focus-visible,.button:focus-visible,a:focus-visible{outline:2px solid #2563eb;outline-offset:3px}.panel{background:#fff;border:1px solid #dfe7f2;border-radius:12px;padding:24px;margin:20px 0;box-shadow:0 2px 8px #17233b03;min-width:0}.panel:last-child{margin-bottom:0}.section-title{align-items:flex-start;flex-wrap:wrap;margin-bottom:10px}.actions{display:flex;gap:8px;flex-wrap:wrap;min-width:0}.button{display:inline-flex;align-items:center;justify-content:center;font:inherit;font-size:12px;font-weight:600;line-height:1.5;min-height:38px;padding:8px 12px;border-radius:8px;background:#2563eb;color:#fff;border:1px solid #2563eb;cursor:pointer;max-width:100%;text-align:center}.button:hover:not(:disabled){background:#1d4ed8;border-color:#1d4ed8}.button.secondary{background:#fff;border-color:#cbd5e1;color:#334e75}.button.secondary:hover:not(:disabled){background:#f1f6ff;border-color:#9ab8ef}.button.danger{background:#fff;border-color:#efc4cd;color:#b4233a}.button.danger:hover:not(:disabled){background:#fff1f3;border-color:#eaa5b4}.button:disabled{opacity:.5;cursor:default}.badge{font-size:11px;white-space:normal;color:#526780;background:#f1f5fc;border:1px solid #e1e8f3;padding:4px 8px;border-radius:20px}.provider-detail,.login{margin:18px 0;padding:18px;border:1px solid #dfe7f2;border-radius:10px;background:#f8faff;min-width:0}.provider-detail .actions{margin-top:12px}.connection{padding:18px 0;border-top:1px solid #e2e8f0;align-items:flex-start}.connection>div:first-child{min-width:0;flex:1}.connection .actions{justify-content:flex-end;flex:none;max-width:55%}.connection strong{font-size:14px;font-weight:600}.connection p{font-size:12px}.alert,.notice{padding:12px 15px;border-radius:9px}.alert{background:#fff1f3;border:1px solid #fecdd3;color:#9f1239}.notice{background:#ecfdf5;border:1px solid #bbf7d0;color:#166534}a{color:#1d4ed8;text-decoration:underline;text-underline-offset:3px}code{display:block;font-size:17px;padding:12px;background:#fff;border:1px solid #dfe7f2;border-radius:8px;color:#17233b;overflow-wrap:anywhere}
@media(max-width:680px){header,.connection{align-items:flex-start;flex-direction:column;gap:12px}.providers{max-width:100%}h2{font-size:23px}.panel{padding:18px;margin:16px 0}.button{min-height:40px}.connection .actions{max-width:100%;justify-content:flex-start}.section-title{gap:8px}.provider-detail,.login{padding:14px}.actions{gap:6px}}
.consent-label{flex-direction:row;align-items:flex-start;gap:10px;font-weight:400}.consent-label input{width:16px;min-height:16px;height:16px;flex:none;margin-top:3px;accent-color:#2563eb}
</style>
